一、购物车页面第一次接触WooCommerce商城的朋友，请参考：WordPress商城搭建-WooCommerce安装和Paypal,支付宝,微信设置。注意：代码如果没有特别说明，就放在functions.php文件的”?&gt;”前面。

1.1  在购物车中排除已设置为隐藏的产品WooCommerce有些设置为隐藏的商品，如果用户购买了后会显示在购物车中，利用以下代码就可以将设置为隐藏的产品在购物车中不可见。
/** * @snippet       Exclude Hidden Products from Cart Count - WooCommerce * @author        Rodolfo Melogli * @compatible    WooCommerce 3.4.5 */// PLEASE NOTE: EMPTY THE CART BEFORE TESTINGadd_filter( &#x27;woocommerce_cart_contents_count&#x27;, &#x27;bbloomer_exclude_hidden_minicart_counter&#x27; );function bbloomer_exclude_hidden_minicart_counter( $quantity ) &#123;  $hidden = 0;  foreach( WC()-&gt;cart-&gt;get_cart() as $cart_item ) &#123;	 $product = $cart_item[&#x27;data&#x27;];	 if ( $product-&gt;get_catalog_visibility() == &#x27;hidden&#x27; ) $hidden += $cart_item[&#x27;quantity&#x27;];  &#125;  $quantity -= $hidden;  return $quantity;&#125;

1.2  若商品在购物车中已存在，则重名“添加到购物车”按钮如果想要WooCommerce在用户点击添加到购物车后，提示该商品已经在购物车中了，你可以用以下方法。
/*** @snippet       Change &quot;Add to Cart&quot; Button Label if Product Already @ Cart* @testedwith    Woo 3.3.4*/// Part 1// Edit Single Product Page Add to Cartadd_filter( &#x27;woocommerce_product_single_add_to_cart_text&#x27;, &#x27;bbloomer_custom_add_cart_button_single_product&#x27; );function bbloomer_custom_add_cart_button_single_product( $label ) &#123;foreach( WC()-&gt;cart-&gt;get_cart() as $cart_item_key =&gt; $values ) &#123;$product = $values[&#x27;data&#x27;];if( get_the_ID() == $product-&gt;get_id() ) &#123;$label = __(&#x27;已添加到购物车，还要一个?&#x27;, &#x27;woocommerce&#x27;);&#125;&#125;return $label;&#125;// Part 2// Edit Loop Pages Add to Cartadd_filter( &#x27;woocommerce_product_add_to_cart_text&#x27;, &#x27;bbloomer_custom_add_cart_button_loop&#x27;, 99, 2 );function bbloomer_custom_add_cart_button_loop( $label, $product ) &#123;if ( $product-&gt;get_type() == &#x27;simple&#x27; &amp;&amp; $product-&gt;is_purchasable() &amp;&amp; $product-&gt;is_in_stock() ) &#123;foreach( WC()-&gt;cart-&gt;get_cart() as $cart_item_key =&gt; $values ) &#123;$_product = $values[&#x27;data&#x27;];if( get_the_ID() == $_product-&gt;get_id() ) &#123;$label = __(&#x27;已添加到购物车，还要一个?&#x27;, &#x27;woocommerce&#x27;);&#125;&#125;&#125;return $label;&#125;


1.3  调整货币符号将澳元的货币符号从默认的$改为AUD$。
function change_existing_currency_symbol( $currency_symbol, $currency ) &#123;    switch( $currency ) &#123;        case &#x27;AUD&#x27;: $currency_symbol = &#x27;AUD$&#x27;; break;    &#125;    return $currency_symbol;&#125;add_filter(&#x27;woocommerce_currency_symbol&#x27;, &#x27;change_existing_currency_symbol&#x27;, 10, 2);

二、店铺首页
2.1  在店铺页面按照库存排序显示产品WooCommerce默认的的店铺首页会有按钮热度、关注度、价格等来排序，我们可以自己添加一个自定义排序，设置按照产品库存排序。
1: Sort Products by Stock Status @ WooCommerce Shop
/*** @snippet       Sort Products By Stock Status - WooCommerce Shop*/add_action( &#x27;woocommerce_product_query&#x27;, &#x27;bbloomer_sort_by_stock_status_then_alpha&#x27;, 999 );function bbloomer_sort_by_stock_status_then_alpha( $query ) &#123;if ( is_admin() ) return;$query-&gt;set( &#x27;meta_key&#x27;, &#x27;_stock_status&#x27; );$query-&gt;set( &#x27;orderby&#x27;, array( &#x27;meta_value&#x27; =&gt; &#x27;ASC&#x27; ) );&#125;

2: Sort Products SHORTCODE by Stock Status
/*** @snippet       Sort Products Shortcode By Stock Status* @author        Rodolfo Melogli* @compatible    WooCommerce 3.4.5*/// Note: products shortcode docs https://docs.woocommerce.com/document/woocommerce-shortcodes/#section-6// In order for the snippet to work, you must add the parameter orderby = &quot;stock&quot; to the shortcode// You can add more parameters to it of course e.g. limit, paginate, etc. It&#x27;s all in the docsadd_filter(&#x27;woocommerce_shortcode_products_query&#x27;, &#x27;bbloomer_sort_by_stock_status_shortcode&#x27;, 999, 3);function bbloomer_sort_by_stock_status_shortcode( $args, $atts, $type ) &#123;if ( $atts[&#x27;orderby&#x27;] == &quot;stock&quot; ) &#123;$args[&#x27;orderby&#x27;]  = array( &#x27;meta_value&#x27; =&gt; &#x27;ASC&#x27; );$args[&#x27;meta_key&#x27;] = &#x27;_stock_status&#x27;;&#125;return $args;&#125;

2.2  在店铺首页中显示商品品牌WooCommerce默认的不会显示某一个产品的品牌，当然我们可以用以下方法搞定：
add_action( &#x27;woocommerce_after_shop_loop_item_title&#x27;, &#x27;bbloomer_show_woocommerce_brands_loop&#x27;, 8 ); function bbloomer_show_woocommerce_brands_loop() &#123;    global $post;    echo get_brands( $post-&gt;ID );&#125;

2.3  在店铺显示某用户已经购买过某商品add_action( &#x27;woocommerce_after_shop_loop_item&#x27;, &#x27;user_logged_in_product_already_bought&#x27;, 30 ); function user_logged_in_product_already_bought() &#123;if ( is_user_logged_in() ) &#123;global $product;$current_user = wp_get_current_user();if ( wc_customer_bought_product( $current_user-&gt;user_email, $current_user-&gt;ID, $product-&gt;get_id() ) ) echo &#x27;♥ Hey &#x27; . $current_user-&gt;first_name . &#x27;, you\&#x27;ve purchased this in the past. Buy again?&#x27;;&#125;&#125;

2.4  禁用或者修改面包屑导航位置删除禁用默认的面包屑导航
remove_action( &#39;woocommerce_before_main_content&#39;``, &#39;woocommerce_breadcrumb&#39;``, 20, 0);
将导航添加到其它位置，例如放在header.php中，则直接在header.php适当位置插入如下代码
if``( function_exists( &#39;woocommerce_breadcrumb&#39;``) ) woocommerce_breadcrumb();
也可以用add_action添加，例如
add_action( &#39;woocommerce_after_main_content&#39;``, &#39;woocommerce_breadcrumb&#39; );
修改面包屑导航的参数：
// Code source： https://gist.github.com/dwiash/4064836function my_woocommerce_breadcrumbs() &#123;    return array(            &#x27;delimiter&#x27;   =&gt; &#x27; / &#x27;,            &#x27;wrap_before&#x27; =&gt; &#x27;&#x27;,            &#x27;wrap_after&#x27;  =&gt; &#x27;&#x27;,            &#x27;before&#x27;      =&gt; &#x27;&#x27;,            &#x27;after&#x27;       =&gt; &#x27;&#x27;,            &#x27;home&#x27;        =&gt; _x( &#x27;Home&#x27;, &#x27;breadcrumb&#x27;, &#x27;woocommerce&#x27; ),        );&#125; add_filter( &#x27;woocommerce_breadcrumb_defaults&#x27;, &#x27;my_woocommerce_breadcrumbs&#x27; );

参数注释：

delimiter：分隔符wrap_before：起始标签wrap_after：结束标签before：起始标签之后、面包屑导航链接之前的内容after：面包屑导航链接之后、结束标签之前的内容home：首页文字，例如像给首页加font-awesome，可以这样设置
&#39;home&#39; =&gt; _x( &#39;&lt;i class=&quot;icon-home&quot;&gt;&lt;/i&gt; Home&#39;``, &#39;breadcrumb&#39;``, &#39;woocommerce&#39; ),

三、单个商品页面
3.1  当产品没有描述时设置一个默认的描述WooCommerce的商品页面如何没有描述会显示空白，这显然不怎么好看，我们可以设置一个段描述用于在没有描述的情况作为默认显示内容。
/** * @snippet       Show Custom Content When Short Description Empty - WooCommerce * @author        Rodolfo Melogli * @compatible    WooCommerce 3.4.5 */add_filter( &#x27;woocommerce_short_description&#x27;, &#x27;bbloomer_echo_short_desc_if_no_short_desc&#x27; );function bbloomer_echo_short_desc_if_no_short_desc( $post_excerpt ) &#123;	if ( empty ( $post_excerpt ) ) &#123;		$post_excerpt = &#x27;&lt;p class=&quot;default-short-desc&quot;&gt;&#x27;;		$post_excerpt .= &#x27;This is the default, global, short description.&lt;br&gt;It will show if &lt;b&gt;no short description has been entered!&lt;/b&gt;&#x27;;		$post_excerpt .= &#x27;&lt;/p&gt;&#x27;;	&#125;	return $post_excerpt;&#125;

3.2  隐藏相关产品推荐WooCommerce默认的会在商品的页面下方显示4个相关的产品，如果你不想要，可以用以下代码去掉它。
remove_action( &#x27;woocommerce_after_single_product_summary&#x27;, &#x27;woocommerce_output_related_products&#x27;, 20 );


3.3  添加“继续购物”按钮当用户在WooCommerce的产品页面点击添加到购物车后，如果你希望增加一个显示“继续购物”的按钮，可以使用以下代码：

add_action( ‘woocommerce_single_product_summary’, ‘bbloomer_continue_shopping_button’, 31 );
function bbloomer_continue_shopping_button() {  if ( wp_get_referer() ) echo ‘&lt;a class&#x3D;”button continue” href&#x3D;”‘ . wp_get_referer() . ‘”&gt;继续购物’;}

3.4 使用视频作为产品展示而不是静态的图片WooCommerce默认的是用图片作为产品展示，我们也可以使用以下代码来让产品变成视频展示。

add_action( ‘woocommerce_before_single_product’, ‘bbloomer_show_video_not_image’ );
function bbloomer_show_video_not_image() {
&#x2F;&#x2F; Do this for product ID &#x3D; 282 only
if ( is_single( ‘282’ ) ) {
remove_action( ‘woocommerce_before_single_product_summary’, ‘woocommerce_show_product_images’, 20 );
remove_action( ‘woocommerce_product_thumbnails’, ‘woocommerce_show_product_thumbnails’, 20 );
add_action( ‘woocommerce_before_single_product_summary’, ‘bbloomer_show_product_video’, 30 );
}
}
function bbloomer_show_product_video() {
echo ‘’;
&#x2F;&#x2F; get video embed HTML from YouTube
echo ‘&lt;iframe width&#x3D;”560″ height&#x3D;”315″ src&#x3D;”https://wzfou.com/embed/JHN7viKRxbQ?rel=0&amp;showinfo=0″ frameborder&#x3D;”0″ allowfullscreen&gt;’;
echo ‘’;
}

3.5  调整相关产品的数量WooCommerce默认的相关产品数量是4个，你可以自定义显示数量。
add_filter( &#x27;woocommerce_output_related_products_args&#x27;, &#x27;bbloomer_change_number_related_products&#x27;, 9999 ); function bbloomer_change_number_related_products( $args ) &#123; $args[&#x27;posts_per_page&#x27;] = 4; // # of related products $args[&#x27;columns&#x27;] = 4; // # of columns per row return $args;&#125;

四、订单页面
4.1  在WooCommerce订单管理中添加自定义栏以下代码可以在WooCommerce的订单管理页面添加到以国家为参数的列。
/** * @snippet       Add Column to Orders Table (e.g. Billing Country) - WooCommerce * @author        Rodolfo Melogli * @compatible    WooCommerce 3.4.5 */add_filter( &#x27;manage_edit-shop_order_columns&#x27;, &#x27;bbloomer_add_new_order_admin_list_column&#x27; );function bbloomer_add_new_order_admin_list_column( $columns ) &#123;    $columns[&#x27;billing_country&#x27;] = &#x27;Country&#x27;;    return $columns;&#125;add_action( &#x27;manage_shop_order_posts_custom_column&#x27;, &#x27;bbloomer_add_new_order_admin_list_column_content&#x27; );function bbloomer_add_new_order_admin_list_column_content( $column ) &#123;    global $post;    if ( &#x27;billing_country&#x27; === $column ) &#123;        $order = wc_get_order( $post-&gt;ID );        echo $order-&gt;get_billing_country();	     &#125;&#125;

4.2  去掉结算页面的“什么是Paypal”“What is PayPal?”WooCommerce在使用Paypal付款时会显示一个“什么是Paypal”“What is PayPal?”的提示，如果你觉得不好看的话可以用以下方法来删除它：

add_filter( &#39;woocommerce_gateway_icon&#39;``, &#39;bbloomer_remove_what_is_paypal&#39;``, 10, 2 );
function bbloomer_remove_what_is_paypal( $icon_html``, $gateway_id ) &#123;
// the apply_filters comes with 2 parameters: $icon_html, $this-&gt;id
// hence we declare 2 parameters within the function
// and the hook above takes the &quot;2&quot; as we decided to pass 2 variables
if``( &#39;paypal&#39; == $gateway_id ) &#123;
// we use one of the passed variables to make sure we only
// run this function for the gateway ID == &#39;paypal&#39;
$icon_html = &#39;&lt;img src=&quot;wzfou.com/wp-content/plugins/woocommerce/includes/gateways/paypal/assets/images/paypal.png&quot; alt=&quot;PayPal Acceptance Mark&quot;&gt;&#39;``;
// in here we define our own $icon_html
// note there is no mention of the &quot;What is PayPal&quot;
// all we want is to repeat the part with the paypal logo
&#125;
// endif
return $icon_html``;
// we send the $icon_html variable back to the system
// if PayPal, the system will use our custom $icon_html
// if not, the system will use the original $icon_html
&#125;

五、账户页面
5.1  显示用户已经购买过的产品如果你想让用户首先在WooCommerce的个人订单管理页面看到自己曾经购买过的产品列表，可以先在function.php文件中添加以下代码：
/** * @snippet       Display All Products Purchased by User via Shortcode - WooCommerce * @author        Rodolfo Melogli * @compatible    Woo 3.4.5 */ // Note: this will only return purchased products for completed and processing orders add_shortcode( &#x27;my_products&#x27;, &#x27;bbloomer_user_products_bought&#x27; ); function bbloomer_user_products_bought() &#123;global $product, $woocommerce, $woocommerce_loop;$columns = 3;$current_user = wp_get_current_user();$args = array(    &#x27;post_type&#x27; =&gt; &#x27;product&#x27;,    &#x27;post_status&#x27; =&gt; &#x27;publish&#x27;,    &#x27;posts_per_page&#x27; =&gt; -1);$loop = new WP_Query($args); ob_start(); woocommerce_product_loop_start(); while ( $loop-&gt;have_posts() ) : $loop-&gt;the_post();$theid = get_the_ID();if ( wc_customer_bought_product( $current_user-&gt;user_email, $current_user-&gt;ID, $theid ) ) &#123;wc_get_template_part( &#x27;content&#x27;, &#x27;product&#x27; );&#125;endwhile; woocommerce_product_loop_end(); woocommerce_reset_loop();wp_reset_postdata(); return &#x27;&#x27; . ob_get_clean() . &#x27;&#x27;;&#125;

然后在你需要显示用户所购买过的所有产品的页面添加以下短代码即可：
[my_products]

5.2  添加新的菜单到账户中心默认的话，在WooCommerce的账户中心只显示资料、订单、地址、退出等菜单，我们可以用以下方法来添加新的菜单。

&#x2F;&#x2F;添加my-account自定义导航及页面&#x2F;*** @snippet       WooCommerce Add New Tab @ My Account* @credits       https://github.com/woothemes/woocommerce/wiki/2.6-Tabbed-My-Account-page* @author        Rodolfo Melogli* @testedwith    WooCommerce 3.4.5*&#x2F;  &#x2F;&#x2F; ——————&#x2F;&#x2F; 1. Register new endpoint to use for My Account page&#x2F;&#x2F; Note: Resave Permalinks or it will give 404 error function bbloomer_add_premium_support_endpoint() {    add_rewrite_endpoint( ‘premium-support’, EP_ROOT | EP_PAGES );} add_action( ‘init’, ‘bbloomer_add_premium_support_endpoint’ );  &#x2F;&#x2F; ——————&#x2F;&#x2F; 2. Add new query var function bbloomer_premium_support_query_vars( $vars ) {    $vars[] &#x3D; ‘premium-support’;    return $vars;} add_filter( ‘query_vars’, ‘bbloomer_premium_support_query_vars’, 0 );  &#x2F;&#x2F; ——————&#x2F;&#x2F; 3. Insert the new endpoint into the My Account menu function bbloomer_add_premium_support_link_my_account( $items ) {    $items[‘premium-support’] &#x3D; ‘联系我们’;    return $items;} add_filter( ‘woocommerce_account_menu_items’, ‘bbloomer_add_premium_support_link_my_account’ );  &#x2F;&#x2F; ——————&#x2F;&#x2F; 4. Add content to the new endpoint function bbloomer_premium_support_content() {echo ‘联系我们有任何问题，欢迎与站长Qi取得联系。Qi的QQ号：798558110，微信号：iamqimm。添加好友请注明“店铺订单”字样。更多的联系方式在：联系站长。’;&#x2F;&#x2F; echo do_shortcode( ‘ &#x2F;* your shortcode here *&#x2F; ‘ );} add_action( ‘woocommerce_account_premium-support_endpoint’, ‘bbloomer_premium_support_content’ );&#x2F;&#x2F; Note: add_action must follow ‘woocommerce_account_{your-endpoint-slug}_endpoint’ format

六、总结WooCommerce虽然说是国外人开发的插件，但是却提供非常多的Hook，我们可以通过主题的函数文件自定义WooCommerce各种设置，上面的代码只是wzfou.com在使用过程觉得可以用得上的，实际上官方还提供非常多的自定义函数。
当然，也有朋友会觉得修改代码有些困难，WooCommerce其实已经有类似的插件了，例如WooCommerce菜单插件，可以方便你自由地添加自定义链接到“我的账户”中，另外相关WooCommerce优化插件，基本上是整合了以下的代码。

近期在其云否维护客户的网站时，客户要求屏蔽国外IP的访问，因为从日志来看攻击的IP大部分都是来自国外，并且自己的目标用户为国内，所以只允许国内的IP访问网站可阻止绝大多数的CC和DDoS攻击。实际测试后，发现效果还是不错，攻击想要再次攻击成本增加了不少。 不过，随后发现了一个问题，就是使用了Cloudflare CDN后，网站获取到的IP地址都是Cloudflare的CDN节点的，不能得到真实用户的IP地址，防御效果大大折扣。好在Cloudflare已经为我们想到这一点了，将访问者的 IP 地址包含在 X-Forwarded-For 标头和 CF-Connecting-IP 标头。 有了 X-Forwarded-For 标头，如果是Nginx可以使用ngx_http_realip_module模块，如果是Apache，则可以使用mod_remoteip模块来获取用户的真实IP。本篇文章就来分享一下如何编译和启用ngx_http_realip_module模块和mod_remoteip模块来获取用户的真实IP地址。
一般来说CDN厂商都采用了X-Forwarded-For和X-Real_IP等标准协议，所以本文介绍了获取用户真实IP的访问基本上适用于其它的CDN厂商。更多的关于CDN加速和服务器优化加速的方法，这里有：
Cloudflare Partner接入管理Cloudflare CDN-启用Railgun动态加速 又拍云CDN加速申请使用教程-一键镜像,静态动态CDN和免费SSL WordPress开启Nginx fastcgi_cache缓存加速方法-Nginx配置实例
一、Nginx编译ngx_http_realip_module1.1 Oneinstack编译如果用的是Oneinstack一键包，则可以用以下命令来编译ngx_http_realip_module： #下编译安装nginx的时候，都编译安装的哪些模块[root@wzfoume ~]# nginx -V nginx version: nginx/1.14.2built by gcc 4.4.7 20120313 (Red Hat 4.4.7-23) (GCC) built with OpenSSL 1.1.1a 20 Nov 2018TLS SNI support enabledconfigure arguments: --prefix=/usr/local/nginx --user=www --group=www --with-http_stub_status_module --with-http_v2_module --with-http_ssl_module --with-http_gzip_static_module --with-http_realip_module --with-http_flv_module --with-http_mp4_module --with-openssl=../openssl-1.1.1a --with-pcre=../pcre-8.42 --with-pcre-jit --with-ld-opt=-ljemalloc#进入到oneinstack的nginx安装目录下，如果没有请先解压[root@wzfoume src]# cd /root/oneinstack/src[root@wzfoume src]# tar xzf nginx-1.14.2.tar.gz[root@wzfoume src]# cd /root/oneinstack/src/nginx-1.14.2[root@wzfoume nginx-1.14.2]# ./configure --prefix=/usr/local/nginx --user=www --group=www --with-http_stub_status_module --with-http_v2_module --with-http_ssl_module --with-http_gzip_static_module --with-http_realip_module --with-http_flv_module --with-http_mp4_module --with-openssl=../openssl-1.1.1a --with-pcre=../pcre-8.42 --with-pcre-jit --with-ld-opt=-ljemalloc --with-http_realip_modulemake#如果出现错误，应该是依赖路径不对，请cd ..到上一个目录解压相应的软件tar xzf pcre-8.42.tar.gztar xzf openssl-1.0.2q.tar.gztar xzf openssl-1.1.1a.tar.gz#编译完成，备份原先配置，然后替换nginx二进制文件mv /usr/local/nginx/sbin/nginx&#123;,_`date +%F`&#125; #备份nginxcp objs/nginx /usr/local/nginx/sbin#查看是否已经把http_realip_module模块加入进去nginx -V
1.2 LNMP编译如果你用的是LNMP一键包，在lnmp安装目录下找到lnmp.conf编辑它，在Nginx_Modules_Options里加上realip，保存后执行./upgrade.sh nginx来升级下Nginx就可以了。命令如下： Nginx_Modules_Options=&#x27;--with-http_realip_module&#x27;
1.3 BT宝塔面板如果你用的是BT宝塔面板，可以使用以下命令来编译ngx_http_realip_module： #宝塔面板安装模块#先查看一下本机的Nginx配置情况[root@cs ~]# nginx -Vnginx version: nginx/1.14.2built by gcc 4.8.5 20150623 (Red Hat 4.8.5-36) (GCC) built with OpenSSL 1.0.2l 25 May 2017TLS SNI support enabledconfigure arguments: --user=www --group=www --prefix=/www/server/nginx --with-openssl=/www/server/nginx/src/openssl --add-module=/www/server/nginx/src/ngx_devel_kit --add-module=/www/server/nginx/src/lua_nginx_module --add-module=/www/server/nginx/src/ngx_cache_purge --add-module=/www/server/nginx/src/nginx-sticky-module --add-module=/www/server/nginx/src/nginx-http-concat --with-http_stub_status_module --with-http_ssl_module --with-http_v2_module --with-http_image_filter_module --with-http_gzip_static_module --with-http_gunzip_module --with-stream --with-stream_ssl_module --with-ipv6 --with-http_sub_module --with-http_flv_module --with-http_addition_module --with-http_realip_module --with-http_mp4_module --with-ld-opt=-Wl,-E --with-pcre=pcre-8.40 --with-ld-opt=-ljemalloc#开始下载Nginx，这里用的是1.15.1，你也可以下载其它的版本wget http://nginx.org/download/nginx-1.15.1.tar.gztar -xzvf nginx-1.15.1.tar.gzcd nginx-1.15.1#下面的命令只是在上面的Nginx -v得到的配置详情后加上了--with-http_realip_module，目的是为了保持原来的配置不变同时又增加新的模块./configure --user=www --group=www --prefix=/www/server/nginx --with-openssl=/www/server/nginx/src/openssl --add-module=/www/server/nginx/src/ngx_devel_kit --add-module=/www/server/nginx/src/lua_nginx_module --add-module=/www/server/nginx/src/ngx_cache_purge --add-module=/www/server/nginx/src/nginx-sticky-module --add-module=/www/server/nginx/src/nginx-http-concat --with-http_stub_status_module --with-http_ssl_module --with-http_v2_module --with-http_image_filter_module --with-http_gzip_static_module --with-http_gunzip_module --with-stream --with-stream_ssl_module --with-ipv6 --with-http_sub_module --with-http_flv_module --with-http_addition_module --with-http_realip_module --with-http_mp4_module --with-ld-opt=-Wl,-E --with-pcre=pcre-8.40 --with-ld-opt=-ljemalloc --with-http_realip_module#只编译不安装make#先停用Nginx，然后替换新的Nginx并查看模块是否已经加载。命令如下：mv /www/server/nginx/sbin/nginx /www/server/nginx/sbin/nginx-wzfou.backupcp objs/nginx /www/server/nginx/sbin/nginxnginx -V#重启Nginx
二、Nginx设置set_real_ip_from编译好了ngx_http_realip_module，现在我们只需要在Nginx配置文件中添加set_real_ip_from代码，示例如下： set_real_ip_from 222.222.222.222; #这里是需要填写具体的CDN服务器IP地址,可添加多个set_real_ip_from 222.222.111.111; real_ip_header X-Forwarded-For;real_ip_recursive on;
如果你用的是CloudFlare免费CDN，请将以下代码加入到你的Nginx配置文件当中。 location / &#123; set_real_ip_from 103.21.244.0/22; set_real_ip_from 103.22.200.0/22; set_real_ip_from 103.31.4.0/22; set_real_ip_from 104.16.0.0/12; set_real_ip_from 108.162.192.0/18; set_real_ip_from 131.0.72.0/22; set_real_ip_from 141.101.64.0/18; set_real_ip_from 162.158.0.0/15; set_real_ip_from 172.64.0.0/13; set_real_ip_from 173.245.48.0/20; set_real_ip_from 188.114.96.0/20; set_real_ip_from 190.93.240.0/20; set_real_ip_from 197.234.240.0/22; set_real_ip_from 198.41.128.0/17; set_real_ip_from 199.27.128.0/21; set_real_ip_from 2400:cb00::/32; set_real_ip_from 2606:4700::/32; set_real_ip_from 2803:f800::/32; set_real_ip_from 2405:b500::/32; set_real_ip_from 2405:8100::/32; set_real_ip_from 2c0f:f248::/32; set_real_ip_from 2a06:98c0::/29; # use any of the following two real_ip_header CF-Connecting-IP; #real_ip_header X-Forwarded-For; &#125;#不要忘记重启nginxservice nginx restart
一般来说CloudFlare的IP地址是不会变的，你可以在这里找到：https://www.cloudflare.com/ips/，但是为了以防万一，wzfou.com建议设置一个自动更新CloudFlare的IP的定时任务，自动将最新的IP添加到Nginx的配置文件当中。代码如下： #在nginx配置目录创建cloudflare_ip.conf文件touch /usr/local/nginx/conf/cloudflare_ip.conf#修改原有的vhost配置，将原来第五步配置的信息改为include cloudflare_ip.conf;#创建自更新脚本update_cloudflare_ip.sh（假定该文件放在 /root 目录下），内容如下：#!/bin/bashecho &quot;#Cloudflare&quot; &gt; /usr/local/nginx/conf/cloudflare_ip.conf;for i in `curl https://www.cloudflare.com/ips-v4`; do echo &quot;set_real_ip_from $i;&quot; &gt;&gt; /usr/local/nginx/conf/cloudflare_ip.conf;donefor i in `curl https://www.cloudflare.com/ips-v6`; do echo &quot;set_real_ip_from $i;&quot; &gt;&gt; /usr/local/nginx/conf/cloudflare_ip.conf;doneecho &quot;&quot; &gt;&gt; /usr/local/nginx/conf/cloudflare_ip.conf;echo &quot;# use any of the following two&quot; &gt;&gt; /usr/local/nginx/conf/cloudflare_ip.conf;echo &quot;real_ip_header CF-Connecting-IP;&quot; &gt;&gt; /usr/local/nginx/conf/cloudflare_ip.conf;echo &quot;#real_ip_header X-Forwarded-For;&quot; &gt;&gt; /usr/local/nginx/conf/cloudflare_ip.conf;#配置crontab 每周一的上午5点更新0 5 * * 1 /bin/bash /root/update_cloudflare_ip.sh
三、Apache配置mod_remoteip模块3.1 apache 2.4apache 2.4自带mod_remoteip模块不需要安装，按照下文操作： #启用模块vim /usr/local/apache/conf/httpd.confInclude conf/extra/httpd-remoteip.conf#添加如下内容vim /usr/local/apache/conf/extra/httpd-remoteip.confLoadModule remoteip_module modules/mod_remoteip.soRemoteIPHeader X-Forwarded-ForRemoteIPInternalProxy 127.0.0.1/24#CloudFlare IP RangesRemoteIPInternalProxy 103.21.244.0/22RemoteIPInternalProxy 103.22.200.0/22RemoteIPInternalProxy 103.31.4.0/22RemoteIPInternalProxy 104.16.0.0/12RemoteIPInternalProxy 108.162.192.0/18RemoteIPInternalProxy 131.0.72.0/22RemoteIPInternalProxy 141.101.64.0/18RemoteIPInternalProxy 162.158.0.0/15RemoteIPInternalProxy 172.64.0.0/13RemoteIPInternalProxy 173.245.48.0/20RemoteIPInternalProxy 188.114.96.0/20RemoteIPInternalProxy 190.93.240.0/20RemoteIPInternalProxy 197.234.240.0/22RemoteIPInternalProxy 198.41.128.0/17 #你的CDN的IP，可以重复添加#修改日志格式，在日志格式中加上%a，然后重启apache即可LogFormat &quot;%h %a %l %u %t \&quot;%r\&quot; %&gt;s %b \&quot;%&#123;Referer&#125;i\&quot; \&quot;%&#123;User-Agent&#125;i\&quot;&quot; combinedLogFormat &quot;%h %a %l %u %t \&quot;%r\&quot; %&gt;s %b&quot; commonLogFormat &quot;%h %l %u %t \&quot;%r\&quot; %&gt;s %b \&quot;%&#123;Referer&#125;i\&quot; \&quot;%&#123;User-Agent&#125;i\&quot; %I %O&quot; combined
3.2 apache 2.2apache 2.2需要安装mod_remoteip模块，方法如下： wget https://github.com/ttkzw/mod_remoteip-httpd22/raw/master/mod_remoteip.c/usr/local/apache/bin/apxs -i -c -n mod_remoteip.so mod_remoteip.c#启用模块vim /usr/local/apache/conf/httpd.confInclude conf/extra/httpd-remoteip.conf#添加如下内容，然后重启apache即可vim /usr/local/apache/conf/extra/httpd-remoteip.confLoadModule remoteip_module modules/mod_remoteip.soRemoteIPHeader X-Forwarded-ForRemoteIPInternalProxy 127.0.0.1 #你的CDN的IP，可以重复添加
四、网站仅允许Cloudflare CDN的IP访问上面我们是通过安装ngx_http_realip_module和mod_remoteip模块获取到了用户真实的IP地址，但是有的时候我们需要借助Cloudflare 的安全防护功能来防止CC或者DDoS攻击，即仅允许Cloudflare CDN的IP访问我们的访问。 Nginx直接拒绝和允许IP访问代码示例如下： location / &#123; deny 192.168.1.1; allow 192.168.1.0/24; allow 10.1.1.0/16; allow 2001:0db8::/32; #Railgun IP deny all;&#125;
如果我们仅允许Cloudflare CDN的IP访问网站，我们可以直接在nginx配置中将Cloudflare CDN的IP添加到允许的范围内。 #直接加入# https://www.cloudflare.com/ips# IPv4allow 103.21.244.0/22;allow 103.22.200.0/22;allow 103.31.4.0/22;allow 104.16.0.0/12;allow 108.162.192.0/18;allow 131.0.72.0/22;allow 141.101.64.0/18;allow 162.158.0.0/15;allow 172.64.0.0/13;allow 173.245.48.0/20;allow 188.114.96.0/20;allow 190.93.240.0/20;allow 197.234.240.0/22;allow 198.41.128.0/17;# IPv6allow 2400:cb00::/32;allow 2405:8100::/32;allow 2405:b500::/32;allow 2606:4700::/32;allow 2803:f800::/32;allow 2c0f:f248::/32;allow 2a06:98c0::/29;
自动更新Cloudflare CDN的IP。手动添加Cloudflare CDN的IP到Nginx配置当中简单方便，但是一旦Cloudflare CDN的IP有变化时还得自己手动处理，我们可以创建一个脚本，定时去更新Cloudflare CDN的IP，自动添加到Nginx配置中，代码如下： touch /usr/local/nginx/conf/allow_ip.conf#修改网站nginx配置，加入以下代码：include /usr/local/nginx/conf/allow_ip.conf;vim /data/script/allow_cf_ip.sh#!/bin/bashecho &quot;#Cloudflare&quot; &gt; /usr/local/nginx/conf/allow_ip.conf;for i in `curl https://www.cloudflare.com/ips-v4`; do echo &quot;allow $i;&quot; &gt;&gt; /usr/local/nginx/conf/allow_ip.conf;donefor i in `curl https://www.cloudflare.com/ips-v6`; do echo &quot;allow $i;&quot; &gt;&gt; /usr/local/nginx/conf/allow_ip.conf;done#添加定时任务0 5 * * 1 /bin/bash /data/script/allow_cf_ip.sh
五、总结使用了CDN加速后，我们的网站获取到的用户IP变成了CDN的IP了，想要获取到用户的真实IP就得利用Nginx和Apache的模式功能。当然，如果你用的是PHP,例如Wordpress，直接将以下代码加入到你的Wordpress配置文件当中即可。 if(isset($_SERVER[&#x27;HTTP_X_FORWARDED_FOR&#x27;]))&#123;$list = explode(‘,’,$_SERVER[&#x27;HTTP_X_FORWARDED_FOR&#x27;]);$_SERVER[&#x27;REMOTE_ADDR&#x27;] = $list[0];&#125;
这里还要特别提醒一下，如果你启用了Cloudflare Railgun动态加速（挖站否的Cloudflare Partner接入管理就提供此免费服务）,记得将Railgun的服务器IP加入到配置当中，因为启用了Railgun后网站获取到的IP地址都来自Railgun服务器上的。

现在搭建网站，有面向国外的，有面向国外，还有一些是面向特定用户的。有朋友在其云否主机上搭建了外贸站，想要设置一下不让国内的竞争同行访问，需要精确到国内某一个省。要想达到这样的效果，就需要利用到IP库了。 现在市面上有不少的运营商提供免费的IP库API可供使用，例如淘宝的IP库、IPIP的IP库还有IP138的IP库，这些IP库都是比较精准的，而且官方提供了详细的PHP、JS、ASP等示例文档，有需要的朋友可以参考文档稍微修改就可以拿来用了。 需要注意的是，IP库在线查询一般会设置有一定的频率限制，例如淘宝的IP库如果一定时间内请求太快的话很容易就变成了502错误了，对企业用户可以选择这些IP库的付费版，可以解决免费IP库各个版本的限制。 对于一些离线的IP库，有的可能好久没有更新了，例如本文介绍的ipdatabase-二叉树快速搜索IP地址数据库，数据源采用2015年广告协会制定的IP地址标准数据库，中国互联网广告行业统一采用的标准IP库。
这篇文章就来搜集整理一下网站限制IP访问的方法，以及梳理一下国内外免费在线和离线的IP库，方便大家使用。更多的站长工具，你还需要：
Paypal通过Payoneer提现到国内银行全过程-新Paypal余额提现方法 网络监控工具:SmokePing Nginx一键安装&#x2F;管理脚本和Looking Glass中文汉化 一软在手截图无忧:ShareX截图神器-短小精悍功能完备 自动化任务可截动图截视频
PS：2018年3月6日更新，如果想要阻止特定的IP访问网站，可以采用该方法：网站屏蔽和阻止特定地区和国家的IP访问设置方法-PHP代码&#x2F;Nginx&#x2F;WordPress设置。 一、PHP代码-禁止IP访问网站如果你想要禁止某一个国家的IP访问你的网站，请使用以下PHP代码：（如果是WP把这段代码加到Header.php中） &lt;?php/** * * test.php(屏蔽国家IP) * */$verification = &#x27;美国&#x27;;//需要屏蔽国家的IPfunction get_client_ip() &#123; $ip = $_SERVER[&#x27;REMOTE_ADDR&#x27;]; if (isset($_SERVER[&#x27;HTTP_X_REAL_FORWARDED_FOR&#x27;]) &amp;&amp; preg_match(&#x27;/^([0-9]&#123;1,3&#125;\.)&#123;3&#125;[0-9]&#123;1,3&#125;$/&#x27;, $_SERVER[&#x27;HTTP_X_REAL_FORWARDED_FOR&#x27;])) &#123; $ip = $_SERVER[&#x27;HTTP_X_REAL_FORWARDED_FOR&#x27;]; &#125; elseif (isset($_SERVER[&#x27;HTTP_X_FORWARDED_FOR&#x27;]) &amp;&amp; preg_match(&#x27;/^([0-9]&#123;1,3&#125;\.)&#123;3&#125;[0-9]&#123;1,3&#125;$/&#x27;, $_SERVER[&#x27;HTTP_X_FORWARDED_FOR&#x27;])) &#123; $ip = $_SERVER[&#x27;HTTP_X_FORWARDED_FOR&#x27;]; &#125; elseif (isset($_SERVER[&#x27;HTTP_CLIENT_IP&#x27;]) &amp;&amp; preg_match(&#x27;/^([0-9]&#123;1,3&#125;\.)&#123;3&#125;[0-9]&#123;1,3&#125;$/&#x27;, $_SERVER[&#x27;HTTP_CLIENT_IP&#x27;])) &#123; $ip = $_SERVER[&#x27;HTTP_CLIENT_IP&#x27;]; &#125; return $ip; &#125;$ip = get_client_ip();//获取访客IP$antecedents = $_SERVER[&#x27;HTTP_REFERER&#x27;];//访客来路地址$result = file_get_contents(&quot;http://ip.taobao.com/service/getIpInfo.php?ip=&quot;.$ip);//IP数据库来自淘宝。$address = json_decode($result,true);//判断访客是否属于美国，是否来自百度，是否来自谷歌if($address[&#x27;data&#x27;][&#x27;country&#x27;] == $verification &amp;&amp; strpos($antecedents, &#x27;baidu&#x27;) === false &amp;&amp; strpos($antecedents, &#x27;google&#x27;) === false)&#123; sleep(10);//设置一个10秒等待。 header(&#x27;HTTP/1.1 503 Service Temporarily Unavailable&#x27;); header(&#x27;Status: 503 Service Temporarily Unavailable&#x27;); header(&#x27;Retry-After: 3600000&#x27;); exit;&#125;?&gt;
如果你想要禁止某一个省份的IP访问你的网站，请使用以下PHP代码： &lt;?php/** * * test.php(屏蔽地方IP) * */$verification = &#x27;江西省&#x27;;//需要屏蔽省份的IPfunction get_client_ip() &#123; $ip = $_SERVER[&#x27;REMOTE_ADDR&#x27;]; if (isset($_SERVER[&#x27;HTTP_X_REAL_FORWARDED_FOR&#x27;]) &amp;&amp; preg_match(&#x27;/^([0-9]&#123;1,3&#125;\.)&#123;3&#125;[0-9]&#123;1,3&#125;$/&#x27;, $_SERVER[&#x27;HTTP_X_REAL_FORWARDED_FOR&#x27;])) &#123; $ip = $_SERVER[&#x27;HTTP_X_REAL_FORWARDED_FOR&#x27;]; &#125; elseif (isset($_SERVER[&#x27;HTTP_X_FORWARDED_FOR&#x27;]) &amp;&amp; preg_match(&#x27;/^([0-9]&#123;1,3&#125;\.)&#123;3&#125;[0-9]&#123;1,3&#125;$/&#x27;, $_SERVER[&#x27;HTTP_X_FORWARDED_FOR&#x27;])) &#123; $ip = $_SERVER[&#x27;HTTP_X_FORWARDED_FOR&#x27;]; &#125; elseif (isset($_SERVER[&#x27;HTTP_CLIENT_IP&#x27;]) &amp;&amp; preg_match(&#x27;/^([0-9]&#123;1,3&#125;\.)&#123;3&#125;[0-9]&#123;1,3&#125;$/&#x27;, $_SERVER[&#x27;HTTP_CLIENT_IP&#x27;])) &#123; $ip = $_SERVER[&#x27;HTTP_CLIENT_IP&#x27;]; &#125; return $ip; &#125;$ip = get_client_ip();//获取访客IP$antecedents = $_SERVER[&#x27;HTTP_REFERER&#x27;];//访客来路地址$result = file_get_contents(&quot;http://ip.taobao.com/service/getIpInfo.php?ip=&quot;.$ip);//IP数据库来自淘宝。$address = json_decode($result,true);//判断访客是否属于江西省，是否来自百度，是否来自谷歌if($address[&#x27;data&#x27;][&#x27;region&#x27;] == $verification &amp;&amp; strpos($antecedents, &#x27;baidu&#x27;) === false &amp;&amp; strpos($antecedents, &#x27;google&#x27;) === false)&#123; sleep(99999999);//设置一个999999秒的等待。 Header(&quot;HTTP/1.1 204 No Content&quot;); exit;&#125;?&gt;
聪明的朋友一定发现了以上代码其实还可以精确到市一级IP，你只需要替换成city就可以了，代码引用淘宝IP库的格式如下： 二、JS代码-禁止IP访问网站当特定省份和城市的IP访问你的网站时，使用以下代码可以弹出提示： &lt;script type=&quot;text/javascript&quot; src=&quot;https://ip.ws.126.net/ipquery&quot;&gt;&lt;/script&gt;&lt;script&gt;var province=localAddress.province;//获取所在省，比如广东省var city=localAddress.city;//获取所在市，比如广州市//判断省if(province.indexOf(&#x27;广东&#x27;) != -1)&#123; alert(province); &#125;else&#123; &#125;//判断市if(city.indexOf(&#x27;广州&#x27;) != -1)&#123; alert(city); &#125;else&#123; &#125;&lt;/script&gt;
当特定省份和城市的IP访问你的网站时，使用以下代码跳转到某一个网址：（其它动作可以根据自定义） &lt;script src=&quot;https://cdn.bootcss.com/jquery/1.10.2/jquery.min.js&quot;&gt;&lt;/script&gt;&lt;script&gt;$.getScript(&#x27;https://ip.ws.126.net/ipquery&#x27;, function()&#123; console.log(localAddress.city) if(localAddress.city.indexOf(&#x27;北京&#x27;) != -1||localAddress.city.indexOf(&#x27;杭州&#x27;) != -1||localAddress.city.indexOf(&#x27;上海&#x27;) != -1||localAddress.city.indexOf(&#x27;广州&#x27;) != -1||localAddress.city.indexOf(&#x27;深圳&#x27;) != -1||localAddress.city.indexOf(&#x27;东莞&#x27;) != -1||localAddress.city.indexOf(&#x27;房山&#x27;) != -1)&#123; window.location.href = &#x27;https://www.baidu.com&#x27;; &#125;else&#123; return; &#125; console.log(localAddress.province) if(localAddress.province.indexOf(&#x27;福建&#x27;) != -1)&#123; window.location.href = &#x27;https://www.baidu.com&#x27;; &#125;else&#123; return; &#125; &#125;);&lt;/script&gt;
三、免费在线和离线IP库汇总3.1 淘宝IP库 http://ip.taobao.com/
访问方式：http://ip.taobao.com/service/getIpInfo.php?ip=\[ip地址字串\]，返回内容以json格式。优点：精准度非常高。不足之处：不支持Https。每个用户的访问频率需小于10qps。示例： #调用 http://ip.taobao.com/service/getIpInfo.php?ip=171.208.203.169#返回&#123;&quot;code&quot;:0,&quot;data&quot;:&#123;&quot;ip&quot;:&quot;171.208.203.169&quot;,&quot;country&quot;:&quot;中国&quot;,&quot;area&quot;:&quot;&quot;,&quot;region&quot;:&quot;四川&quot;,&quot;city&quot;:&quot;乐山&quot;,&quot;county&quot;:&quot;XX&quot;,&quot;isp&quot;:&quot;电信&quot;,&quot;country_id&quot;:&quot;CN&quot;,&quot;area_id&quot;:&quot;&quot;,&quot;region_id&quot;:&quot;510000&quot;,&quot;city_id&quot;:&quot;511100&quot;,&quot;county_id&quot;:&quot;xx&quot;,&quot;isp_id&quot;:&quot;100017&quot;&#125;&#125;
3.2 网易IP库 https://ip.ws.126.net/ipquery
示例： #调用https://ip.ws.126.net/ipquery?ip=171.208.203.169#返回var lo=&quot;四川省&quot;, lc=&quot;乐山市&quot;; var localAddress=&#123;city:&quot;乐山市&quot;, province:&quot;四川省&quot;&#125;
3.3 搜狐IP库 http://pv.sohu.com/cityjson
3.4 IPIP.net IP库 https://www.ipip.net/support/api.html
IPIP.net IP免费接口，限速每天1000次，示例： #调用http://freeapi.ipip.net/118.28.8.8#返回[&quot;中国&quot;,&quot;天津&quot;,&quot;天津&quot;,&quot;&quot;,&quot;鹏博士&quot;]
3.5 IP.la IP库 https://www.ip.la/
IP.la 是IPIP.net 搞的海外版，官网说“You can initiate requests without any limit.”示例： &lt;?php $ip = file_get_contents(&#x27;https://api.ip.la&#x27;); echo &quot;My public IP address is: &quot; . $ip;?&gt;
3.6 IP138 IP查询 http://user.ip138.com/ip/
示例： #接口地址http协议：http://api.ip138.com/query/https协议：https://api.ip138.com/query/#调用http://api.ip138.com/query/?ip=8.8.8.8&amp;callback=find&amp;oid=&#123;oid&#125;&amp;mid=&#123;mid&#125;&amp;sign=签名算法
3.7 百度地图IP查询 http://lbsyun.baidu.com/
示例： #调用https://api.map.baidu.com/location/ip?ak=F454f8a5efe5e577997931cc01de3974&amp;ip=118.28.8.8#返回&#123;&quot;address&quot;:&quot;CN|\u5929\u6d25|\u5929\u6d25|None|DXTNET|0|0&quot;,&quot;content&quot;:&#123;&quot;address_detail&quot;:&#123;&quot;province&quot;:&quot;\u5929\u6d25\u5e02&quot;,&quot;city&quot;:&quot;\u5929\u6d25\u5e02&quot;,&quot;district&quot;:&quot;&quot;,&quot;street&quot;:&quot;&quot;,&quot;street_number&quot;:&quot;&quot;,&quot;city_code&quot;:332&#125;,&quot;address&quot;:&quot;\u5929\u6d25\u5e02&quot;,&quot;point&quot;:&#123;&quot;y&quot;:&quot;4715083.22&quot;,&quot;x&quot;:&quot;13047990&quot;&#125;&#125;,&quot;status&quot;:0&#125;
3.8 腾讯位置服务 https://lbs.qq.com/webservice\_v1/guide-ip.html
示例： #调用https://apis.map.qq.com/ws/location/v1/ip?ip=61.135.17.68&amp;key=OB4BZ-D4W3U-B7VVO-4PJWW-6TKDJ-WPB77#返回&#123; &quot;status&quot;: 0, &quot;message&quot;: &quot;query ok&quot;, &quot;result&quot;: &#123; &quot;ip&quot;: &quot;61.135.17.68&quot;, &quot;location&quot;: &#123; &quot;lng&quot;: 116.407526, &quot;lat&quot;: 39.90403 &#125;, &quot;ad_info&quot;: &#123; &quot;nation&quot;: &quot;中国&quot;, &quot;province&quot;: &quot;&quot;, &quot;city&quot;: &quot;&quot;, &quot;district&quot;: &quot;&quot;, &quot;adcode&quot;: 110000 &#125; &#125;&#125;
3.9 ipdatabase-二叉树快速搜索IP地址数据库 https://github.com/wzhe06/ipdatabase
数据源采用2015年广告协会制定的IP地址标准数据库，利用二叉树实现IP查询，首先将10进制IPV4地址转化为二进制构建二叉树，利用二叉树搜索进行搜索，示例： public void example() throws Exception &#123; String ip = &quot;58.30.15.255&quot;; String region = IpHelper.findRegionByIp(ip); System.out.println(region);&#125;
3.10 ip2region-Binary,B树和纯内存三种查询IP库 https://github.com/lionsoul2014/ip2region
该数据聚合了一些知名ip到地名查询提供商的数据，每条ip数据段都固定了格式：_城市Id|国家|区域|省份|城市|ISP，_中国的数据精确到了城市，其他国家只能定位到国家。示例： #调用php binding/php/testSearcher.php ./data/ip2region.db#返回initializing B-tree ... +----------------------------------+| ip2region test script || Author: chenxin619315@gmail.com || Type &#x27;quit&#x27; to exit program |+----------------------------------+p2region&gt;&gt; 101.105.35.572163|中国|华南|广东省|深圳市|鹏博士 in 0.02295 millseconds
3.11 纯真IP库 http://www.cz88.net/
四、总结总得来说，免费IP库还是挺多的，无论是付费的IP库或者是免费的IP库都不一定做到100%的准确，尤其是离线的IP库更需要及时更新才可以获取正确的信息。 离线IP库可移植性最强，你可以根据自己的需要整合到JS、PHP、ASP、C#、JAVA等当，在线的IP库API查询受网络以及频率限制的影响，不适用于大型的应用场景。
